const entries = $input.all();
const jobs = $('Trusted job reference').all(0, $runIndex);
if (entries.length !== 1 || jobs.length !== 1) throw new Error('Expected one receipt and one job reference');
const expectedRunId = jobs[0].json.expectedRunId;
const receipt = entries[0].json;
if (typeof expectedRunId !== 'string' || !expectedRunId.trim() || expectedRunId.trim() !== expectedRunId ||
    receipt.runId !== expectedRunId || receipt.actId !== "dulaBRchXhuENMm3d" || receipt.actor !== "albo-gestori-ambientali" ||
    receipt.status !== 'SUCCEEDED') throw new Error('Actor, run or terminal status mismatch');
const {runId, rows} = receipt;

const summary = receipt.summary;
if (!summary || !Number.isInteger(summary.recordsSaved) || summary.recordsSaved < 0 ||
    !Number.isInteger(summary.regionsSearched) || summary.regionsSearched < 1 ||
    !['maxResults', 'endOfResults'].includes(summary.stopReason)) {
  throw new Error('Missing or unsupported registry summary');
}
return [{json:{runId, recordsSaved:summary.recordsSaved, regionsSearched:summary.regionsSearched,
  stopReason:summary.stopReason, decision:summary.stopReason === 'maxResults' ? 'LIMIT_REACHED_REVIEW_SCOPE' : 'REVIEW_OFFICIAL_REGISTER'}}];
